import maxflow.*;
public class Check2 {
  static void run(String label, int[][] m, int s, int t, int expected){
    FlowNetwork n = FlowNetwork.fromMatrix(m);
    int bfs = new FordFulkersonSolver(new BreadthFirstPathFinder()).solve(n,s,t).value();
    int dfs = new FordFulkersonSolver(new DepthFirstPathFinder()).solve(n,s,t).value();
